from .money import MAX_CENTS, cents_to_decimal, format_amount, parse_cents

def make_invoice(amounts):
    if type(amounts) is not list:
        raise ValueError("amounts must be a list")
    total_cents = 0
    for item in amounts:
        total_cents += parse_cents(item)
    if total_cents > MAX_CENTS:
        raise ValueError("total exceeds 1000000.00")
    return {"total": format_amount(cents_to_decimal(total_cents)), "count": len(amounts)}

