import re
from decimal import Decimal

MAX_CENTS = 100_000_000  # 1000000.00

_AMOUNT_STRING = re.compile(r"[+-]?[0-9]+(?:\.[0-9]+)?")


def _cents_from_decimal(value):
    # Only context-free Decimal operations are used here, so the caller's
    # decimal precision, rounding mode and traps cannot affect the result.
    if not value.is_finite():
        raise ValueError("amount must be finite")
    if value.is_zero():
        raise ValueError("amount must be greater than zero")
    if value.is_signed():
        raise ValueError("amount must not be negative")
    # adjusted() is the exponent of the leading digit; 10**7 and up is over the maximum.
    if value.adjusted() > 6:
        raise ValueError("amount exceeds 1000000.00")
    _, digits, exponent = value.as_tuple()
    coefficient = "".join(map(str, digits))
    significant = coefficient.rstrip("0")
    # value == int(significant) * 10**shift exactly.
    shift = exponent + len(coefficient) - len(significant)
    # significant ends in a nonzero digit, so a fraction finer than one cent
    # can never be absorbed; reject it rather than rounding.
    if shift < -2:
        raise ValueError("amount is not exactly representable in cents")
    cents = int(significant) * 10 ** (shift + 2)
    if cents > MAX_CENTS:
        raise ValueError("amount exceeds 1000000.00")
    return cents


def parse_cents(value):
    """Validate an amount and return it as an exact integer count of cents."""
    if isinstance(value, Decimal):
        return _cents_from_decimal(Decimal(value))
    if isinstance(value, str):
        if _AMOUNT_STRING.fullmatch(value) is None:
            raise ValueError("malformed amount string")
        return _cents_from_decimal(Decimal(value))
    if isinstance(value, int) and not isinstance(value, bool):
        number = int.__index__(value)
        if number <= 0:
            raise ValueError("amount must be greater than zero")
        if number > 1000000:
            raise ValueError("amount exceeds 1000000.00")
        return number * 100
    raise ValueError(f"unsupported amount type: {type(value).__name__}")


def cents_to_decimal(cents):
    return Decimal(f"{cents // 100}.{cents % 100:02d}")


def parse_amount(value):
    return cents_to_decimal(parse_cents(value))


def format_amount(value):
    return format(value, ".2f")
